#!/bin/bash
# #447's post-merge-rounds experiment: main (main2/, 53854a7c2) against the same tree with the four post-merge rounds
# on one lane (post1/), each on 2, 3, 4 and 8 forced lanes against one lane in the same process, on the 76 units of
# the deferred-lane-rule-447-2026-11-06 record, three rounds, four holds a round. Waits for both builds first.
cd ~/buster-fast-bench/447-claude
until grep -q '^exit=' logs/build-main2.txt 2>/dev/null && grep -q '^exit=' logs/build-post1.txt 2>/dev/null; do sleep 10; done
grep -q '^exit=0' logs/build-main2.txt && grep -q '^exit=0' logs/build-post1.txt || exit 1
scripts/queue.sh post 3 main2+every:2,post1+every:2,main2+every:3,post1+every:3,main2+every:4,post1+every:4,main2+every:8,post1+every:8 'sqlite musl/locale/iconv.c ' 'cts/00200.c musl/regex/regcomp.c cts/00001.c cts/00169.c cts/00182.c cts/00204.c cts/00213.c musl/string/strlen.c musl/stdlib/qsort.c musl/stdio/vfprintf.c musl/regex/regexec.c musl/malloc/mallocng/malloc.c musl/math/lgamma_r.c musl/math/j0.c musl/crypt/crypt_blowfish.c musl/thread/pthread_create.c musl/internal/floatscan.c musl/math/fmal.c musl/math/exp2l.c musl/math/__rem_pio2_large.c syn/b16x19.c syn/b16x5.c syn/b16x77.c syn/d16x19f384s192.c syn/d16x19f384s288.c ' 'syn/d2x1f384s288.c syn/d2x1f480s240.c syn/h16x1.c syn/h16x10.c syn/h16x154.c syn/h16x19.c syn/h16x2.c syn/h16x38.c syn/h16x5.c syn/h16x77.c syn/h2x160.c syn/h2x240.c syn/h2x320.c syn/h2x40.c syn/h2x480.c syn/h2x80.c syn/h64x1.c syn/h64x10.c syn/h64x3.c syn/l16x10f192.c syn/l16x10f384.c syn/l16x19f192.c syn/l16x19f384.c syn/l16x38f192.c syn/l16x38f384.c ' 'syn/l16x5f384.c syn/l16x77f384.c syn/l4x38f384.c syn/l8x38f384.c syn/x16x10.c syn/x16x19.c syn/x16x38.c syn/x16x77.c musl/stdio/vfwprintf.c musl/stdio/vfscanf.c musl/regex/tre-mem.c musl/time/strftime.c musl/network/getaddrinfo.c musl/network/lookup_name.c musl/misc/nftw.c musl/search/tsearch.c musl/search/hsearch.c musl/crypt/crypt_sha512.c musl/crypt/crypt_des.c musl/process/posix_spawn.c musl/string/memmem.c musl/prng/random.c musl/time/__tz.c musl/multibyte/mbrtowc.c '
